// 检验是否满足要求的函数
bool check(vector<int> ans, int time, int totalDay) {
    int todayCost = 0;
    int maxCost = 0;
    bool canHelp = true;
​
    int day = 1;
    int i = 0;
    int n = ans.size();
    while (i < n) {
        todayCost += ans[i];
        maxCost = max(maxCost, ans[i]);
​
        if (todayCost > time) {
            // 跳过用时最长的题目
            if (canHelp) {
               todayCost -= maxCost;
               canHelp = false;
               i++; 
            } else {
                day++;
                // 重置状态
                todayCost =0;
                maxCost = 0;
                canHelp = true;
            }
        } else {
            i++;
        }    
    }
    return day <= totalDay;
}
