public class Main {
    // 通用 split 函数
    public static List<Integer> parseInput(String s) {
        String[] parts = s.split(",");
        List<Integer> result = new ArrayList<>();
        for (String part : parts) {
            result.add(Integer.parseInt(part));
        }
        return result;
    }
​
    // 检验是否满足要求的函数
    public static boolean check(List<Integer> ans, int time, int totalDay) {
        int todayCost = 0, maxCost = 0;
        boolean canHelp = true;
        int day = 1, i = 0, n = ans.size();
​
        while (i < n) {
            todayCost += ans.get(i);
            maxCost = Math.max(maxCost, ans.get(i));
​
            if (todayCost > time) {
                if (canHelp) {
                    todayCost -= maxCost;
                    canHelp = false;
                    i++;
                } else {
                    day++;
                    todayCost = 0;
                    maxCost = 0;
                    canHelp = true;
                }
            } else {
                i++;
            }
        }
        return day <= totalDay;
    }
