void (async function () {
  const times = (await readline()).split(",").map(Number);
  const m = parseInt(await readline());
​
  // T的初始取值范围
  let low = 0;
  let high = times.reduce((a, b) => a + b) - Math.max(...times);
​
  // 二分
  while (low <= high) {
    // 取中间值尝试
    let mid = (low + high) >> 1;
​
    if (check(mid)) {
      high = mid - 1;
    } else {
      low = mid + 1;
    }
  }
​
  console.log(low);
​
  function check(t) {
    // 今天总耗时
    let sum_cost = 0;
    // 今天耗时最多的题目的耗时
    let max_cost = 0;
    // 今天是否可以申请帮助
    let canHelp = true;
​
    // 第几天
    let day = 1;
​
    let i = 0;
    while (i < times.length) {
      sum_cost += times[i];
      max_cost = Math.max(max_cost, times[i]);
​
      if (sum_cost > t) {
        // 如果做完times[i]，总耗时超过了t
        if (canHelp) {
          // 如果可以申请帮助，那么就看耗时最长的题目的答案
          sum_cost -= max_cost;
          // 今天申请帮助的机会用完了
          canHelp = false;
          // 下面继续做下一题
          i++;
        } else {
          // 如果不能申请帮助，则今天做不了times[i]题目，只能放到明天做
          // 进入明天
          day++;
          // 重置总耗时，最大耗时题目，以及申请帮助机会
          sum_cost = 0;
          max_cost = 0;
          canHelp = true;
        }
      } else {
        // 如果做完times[i]，总耗时没有超过t，则继续做下面的题目
        i++;
      }
    }
​
    return day <= m;
  }
})();

